        require(address(this).balance >= ticketValue);
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.play{value: ticketValue}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        assert(reverted ? potAfter == potBefore : potAfter <= 10);
    }

